//! Parity tests against fixtures generated by
//! `parity/gen_fixtures.py` (`pixi run --manifest-path
//! crates/ports/split_lang/pixi.toml fixtures`).
//!
//! `split_by_lang` needs the fasttext model: set `FAST_LANGDETECT_MODEL` to
//! the path of `lid.176.bin` (the `lid-model` pixi task downloads it to
//! `parity/.cache/fast_langdetect/lid.176.bin`). That test is skipped when
//! it is unset. The budoux test needs no model.

use std::path::PathBuf;
use std::sync::Arc;

use fast_langdetect::{LangDetectConfig, LangDetector, Model};
use serde_json::{Value, json};
use split_lang::budoux;
use split_lang::split::splitter::{LangSplitterOptions, to_owned_map};
use split_lang::{LangSplitter, SplitLangError};

/// `LangSegmenter.DEFAULT_LANG_MAP` of GPT-SoVITS.
const GSV_LANG_MAP: &[(&str, &str)] = &[
  ("zh", "zh"),
  ("yue", "zh"),
  ("wuu", "zh"),
  ("zh-cn", "zh"),
  ("zh-tw", "x"),
  ("ko", "ko"),
  ("ja", "ja"),
  ("en", "en"),
];

/// Inputs whose `split_by_lang` output is known to differ, as
/// `(config, text)` (documented in `parity/README.md`). Empty: every case
/// matches.
const KNOWN_MISMATCHES: &[(&str, &str)] = &[];

fn model_path() -> Option<PathBuf> {
  match std::env::var_os("FAST_LANGDETECT_MODEL") {
    Some(p) => Some(PathBuf::from(p)),
    None => {
      eprintln!(
        "FAST_LANGDETECT_MODEL is not set; skipping (run `pixi run --manifest-path \
         crates/ports/split_lang/pixi.toml lid-model` and point it at \
         crates/ports/split_lang/parity/.cache/fast_langdetect/lid.176.bin)"
      );
      None
    }
  }
}

fn encode(r: Result<Vec<split_lang::SubString>, SplitLangError>) -> Value {
  match r {
    Ok(v) => json!(
      v.iter()
        .map(|s| json!([s.lang, s.text, s.index, s.length]))
        .collect::<Vec<_>>()
    ),
    Err(e) => json!({ "error": e.exception_name() }),
  }
}

#[test]
fn budoux_parse_matches_python() {
  let ja = budoux::load_default_japanese_parser();
  let zh = budoux::load_default_simplified_chinese_parser();
  let mut n = 0;
  for line in include_str!("fixtures/budoux.jsonl").lines() {
    let case: Value = serde_json::from_str(line).unwrap();
    let text = case["text"].as_str().unwrap();
    assert_eq!(json!(ja.parse(text)), case["ja"], "ja.parse({text:?})");
    assert_eq!(json!(zh.parse(text)), case["zh"], "zh.parse({text:?})");
    n += 1;
  }
  eprintln!("budoux: {n} texts matched");
  assert!(n > 1000);
}

#[test]
fn split_by_lang_matches_python() {
  let Some(path) = model_path() else { return };
  let detector = Arc::new(LangDetector::new(
    LangDetectConfig::new(None, Some(path), true, Some(80), Model::Auto).unwrap(),
  ));
  let mut gsv = LangSplitter::new(LangSplitterOptions {
    lang_map: to_owned_map(GSV_LANG_MAP),
    ..LangSplitterOptions::default()
  });
  gsv.detector = Some(detector.clone());
  let mut gsv_no_digit = gsv.clone();
  gsv_no_digit.merge_across_digit = false;
  let default = LangSplitter {
    detector: Some(detector),
    ..LangSplitter::default()
  };

  let configs: [(&str, &LangSplitter); 3] = [
    ("gsv", &gsv),
    ("gsv_no_digit", &gsv_no_digit),
    ("default", &default),
  ];
  let mut cases = std::collections::BTreeMap::<&str, (usize, usize)>::new();
  let mut unexpected = Vec::new();
  let mut seen_known = Vec::new();
  for line in include_str!("fixtures/split_by_lang.jsonl").lines() {
    let case: Value = serde_json::from_str(line).unwrap();
    let text = case["text"].as_str().unwrap();
    for (name, splitter) in configs {
      let Some(expected) = case.get(name) else {
        continue;
      };
      let got = encode(splitter.split_by_lang(text));
      let entry = cases.entry(name).or_default();
      entry.0 += 1;
      let known = KNOWN_MISMATCHES.contains(&(name, text));
      if &got == expected {
        entry.1 += 1;
        assert!(
          !known,
          "{name}({text:?}) is listed as a known mismatch but matches"
        );
      } else if known {
        seen_known.push((name, text.to_string()));
      } else {
        unexpected.push(format!(
          "{name}({text:?}):\n  got      {got}\n  expected {expected}"
        ));
      }
    }
  }
  for (name, (total, matched)) in &cases {
    eprintln!("split_by_lang[{name}]: {matched}/{total} matched");
  }
  assert!(
    unexpected.is_empty(),
    "{} mismatches:\n{}",
    unexpected.len(),
    unexpected[..unexpected.len().min(20)].join("\n")
  );
  assert_eq!(seen_known.len(), KNOWN_MISMATCHES.len());
  assert!(cases["gsv"].0 >= 3000);
}
